'use client';

import type { paths } from '@/types/api-schema';

/**
 * Typed HTTP client for `acne-api`.
 *
 * The types come from `src/types/api-schema.d.ts`, generated by `pnpm generate:api-types` from the
 * backend's own OpenAPI document. This file therefore declares NO response shape of its own,
 * which is the contract rule of section 4: never a hand-written duplicate of another service's
 * schema. If the backend changes a field, `pnpm typecheck` fails here.
 */

const BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3001/api';

const ACCESS_TOKEN_KEY = 'acne.accessToken';
const REFRESH_TOKEN_KEY = 'acne.refreshToken';
const USER_KEY = 'acne.user';

// --- Response type extraction ------------------------------------------------
// Helpers that dig the JSON body out of the generated `paths` map, so every call site gets the
// real backend type without restating it.

type JsonOf<T> = T extends { content: { 'application/json': infer R } } ? R : never;

type OkResponse<T> = T extends { responses: infer R }
  ? R extends { 200: infer Ok }
    ? JsonOf<Ok>
    : R extends { 201: infer Created }
      ? JsonOf<Created>
      : unknown
  : unknown;

/**
 * The OpenAPI document keys every route with the API's global prefix (`/api/auth/login`), while
 * this client carries that prefix in `BASE_URL` and calls the route as `/auth/login`. This alias
 * bridges the two so call sites stay short AND still resolve against the generated schema.
 */
type Prefixed<P extends string> = `/api${P}` extends keyof paths ? `/api${P}` : never;

export type ApiPath = keyof paths extends `/api${infer Rest}` ? `/${Rest}` : string;

export type GetResult<P extends string> = paths[Prefixed<P>] extends { get: infer Op }
  ? OkResponse<Op>
  : never;

export type PostResult<P extends string> = paths[Prefixed<P>] extends { post: infer Op }
  ? OkResponse<Op>
  : never;

export type PatchResult<P extends string> = paths[Prefixed<P>] extends { patch: infer Op }
  ? OkResponse<Op>
  : never;

// --- Session ----------------------------------------------------------------

export type SessionUser = NonNullable<PostResult<'/auth/login'>>['user'];

export interface StoredSession {
  accessToken: string;
  refreshToken: string;
  user: SessionUser;
}

export function readSession(): StoredSession | null {
  if (typeof window === 'undefined') return null;
  try {
    const accessToken = window.localStorage.getItem(ACCESS_TOKEN_KEY);
    const refreshToken = window.localStorage.getItem(REFRESH_TOKEN_KEY);
    const rawUser = window.localStorage.getItem(USER_KEY);
    if (accessToken === null || refreshToken === null || rawUser === null) return null;
    return { accessToken, refreshToken, user: JSON.parse(rawUser) as SessionUser };
  } catch {
    return null;
  }
}

export function writeSession(session: StoredSession): void {
  if (typeof window === 'undefined') return;
  window.localStorage.setItem(ACCESS_TOKEN_KEY, session.accessToken);
  window.localStorage.setItem(REFRESH_TOKEN_KEY, session.refreshToken);
  window.localStorage.setItem(USER_KEY, JSON.stringify(session.user));
}

export function clearSession(): void {
  if (typeof window === 'undefined') return;
  window.localStorage.removeItem(ACCESS_TOKEN_KEY);
  window.localStorage.removeItem(REFRESH_TOKEN_KEY);
  window.localStorage.removeItem(USER_KEY);
}

// --- Errors -----------------------------------------------------------------

export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly payload: unknown = null,
  ) {
    super(message);
    this.name = 'ApiError';
  }

  /**
   * True when the request was rejected by `StudyModeGuard` because the user is in pretest.
   * The portal renders this as an explanatory panel rather than a generic error: it is expected
   * behaviour of the experimental design, not a malfunction (RF-TR-01).
   */
  get isStudyModeBlock(): boolean {
    if (this.status !== 403) return false;
    const payload = this.payload as { requirement?: string } | null;
    return payload?.requirement === 'RF-TR-01';
  }
}

// --- Core -------------------------------------------------------------------

interface RequestOptions {
  method?: 'GET' | 'POST' | 'PATCH' | 'DELETE';
  body?: unknown;
  /** Multipart upload; `body` must be a FormData. */
  formData?: FormData;
  signal?: AbortSignal;
}

async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const session = readSession();
  const headers: Record<string, string> = {};
  if (session !== null) headers['Authorization'] = `Bearer ${session.accessToken}`;

  let body: BodyInit | undefined;
  if (options.formData !== undefined) {
    body = options.formData;
  } else if (options.body !== undefined) {
    headers['Content-Type'] = 'application/json';
    body = JSON.stringify(options.body);
  }

  let response: Response;
  try {
    response = await fetch(`${BASE_URL}${path}`, {
      method: options.method ?? 'GET',
      headers,
      body,
      signal: options.signal,
    });
  } catch (error) {
    throw new ApiError(
      0,
      `No se pudo contactar con la API en ${BASE_URL}. Verifique que acne-api esté levantado.`,
      error,
    );
  }

  if (response.status === 204) return undefined as T;

  const text = await response.text();
  let payload: unknown = null;
  if (text !== '') {
    try {
      payload = JSON.parse(text);
    } catch {
      payload = text;
    }
  }

  if (!response.ok) {
    // A 401 means the session is gone; clearing it lets the guard bounce the user to /login
    // instead of leaving the portal in a half-authenticated state.
    if (response.status === 401) clearSession();
    throw new ApiError(response.status, extractMessage(payload, response.status), payload);
  }

  return payload as T;
}

function extractMessage(payload: unknown, status: number): string {
  if (typeof payload === 'string' && payload !== '') return payload;
  if (typeof payload === 'object' && payload !== null) {
    const record = payload as Record<string, unknown>;
    const message = record['message'];
    if (typeof message === 'string') return message;
    if (Array.isArray(message)) return message.join(' · ');
    if (typeof message === 'object' && message !== null) {
      const nested = (message as Record<string, unknown>)['message'];
      if (typeof nested === 'string') return nested;
    }
  }
  return `La API respondió con estado ${status}.`;
}

// --- Public surface ---------------------------------------------------------

export const api = {
  get: <P extends string>(path: P, query?: QueryParams): Promise<GetResult<P>> =>
    request<GetResult<P>>(withQuery(path, query)),

  /** For paths carrying parameters, already interpolated by the caller. */
  getPath: <T>(path: string, query?: QueryParams): Promise<T> =>
    request<T>(withQuery(path, query)),

  post: <T>(path: string, body?: unknown): Promise<T> =>
    request<T>(path, { method: 'POST', body }),

  patch: <T>(path: string, body?: unknown): Promise<T> =>
    request<T>(path, { method: 'PATCH', body }),

  upload: <T>(path: string, formData: FormData): Promise<T> =>
    request<T>(path, { method: 'POST', formData }),

  /** Absolute URL for a resource the browser loads directly (images, PDFs, CSV). */
  url: (path: string): string => `${BASE_URL}${path}`,

  /** Downloads a binary resource with the bearer token attached. */
  async download(path: string, filename: string): Promise<void> {
    const session = readSession();
    const response = await fetch(`${BASE_URL}${path}`, {
      headers: session === null ? {} : { Authorization: `Bearer ${session.accessToken}` },
    });
    if (!response.ok) {
      throw new ApiError(response.status, `No se pudo descargar el archivo (${response.status}).`);
    }
    const blob = await response.blob();
    const objectUrl = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = objectUrl;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(objectUrl);
  },
};

export type QueryParams = Record<string, string | number | boolean | undefined | null>;

function withQuery(path: string, query?: QueryParams): string {
  if (query === undefined) return path;
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value === undefined || value === null || value === '') continue;
    search.set(key, String(value));
  }
  const serialised = search.toString();
  return serialised === '' ? path : `${path}?${serialised}`;
}

export async function login(email: string, password: string): Promise<StoredSession> {
  const result = await request<NonNullable<PostResult<'/auth/login'>>>('/auth/login', {
    method: 'POST',
    body: { email, password },
  });
  const session: StoredSession = {
    accessToken: result.accessToken,
    refreshToken: result.refreshToken,
    user: result.user,
  };
  writeSession(session);
  return session;
}
